mapper.sql:
t.family_id = #{familyId} AND t.deleted = 0
 AND t.biz_date >= #{q.startDate} 
 AND t.biz_date <= #{q.endDate} 
AND t.type = #{q.type}
AND t.category_id = #{q.categoryId}
AND t.sub_category_id = #{q.subCategoryId}
AND t.account_id = #{q.accountId}
AND t.created_by = #{q.createdBy}
AND t.amount = #{q.amount}
AND t.remark LIKE CONCAT('%', #{q.keyword}, '%')

AND t.rule_id IS NOT NULL
AND t.rule_id IS NULL

FROM `transaction` t
WHERE t.deleted = 0
  AND t.family_id = #{familyId}
  AND t.type = 'EXPENSE'
  AND t.biz_date  >=  #{from}
  AND t.biz_date  <=  #{to}

mapper.select:
SELECT COUNT(DISTINCT t.biz_date)
FROM `transaction` t
WHERE t.family_id = #{familyId}
  AND t.deleted = 0
  AND t.biz_date  >=  #{from}
  AND t.biz_date  <=  #{to}

SELECT t.*

ORDER BY t.biz_date ASC, t.id ASC
LIMIT #{offset}, #{limit}
